>// Test chapter trigger logic when manually adjusting a SagaΓÇÖs lore countdescribe('useGameState ΓÇö manual chapter triggers', () => {  it('setCount triggers new chapters when increasing count past a target', () => {    const { result } = renderHook(() => useGameState());    act(() =>      result.current.addCard(addInput({        mechanic: 'saga',        startingCount: 0,        direction: 'increment',        targetCount: 3,        chapters: ['Chapter I', 'Chapter II', 'Chapter III'],      }));    const cardId = result.current.state.cards[0]!.getInstanceId();    // Initial count should be 0    expect(result.current.state.cards[0]!.count).toBe(0);    // Increase count across single chapter: 0 -> 1 (should not log a chapter yet)    act(() => result.current.setCount(cardId, 1));    expect(result.current.state.cards[0]!.count).toBe(1);    // Double jump (0 -> 3): trigger Chapters I, II, III on set
    act(() => result.current.setCount(cardId, 3));    const lastLog = result.current.state.log.slice(-1);    const chapterTriggers = lastLog.filter(entry => entry?.chapter) as Array<{      chapter: { number: number; text: string };    }>;    expect(chapterTriggers.length).toBe(3);    expect(chapterTriggers[0].chapter.number).toBe(1); // Chapter I
    expect(chapterTriggers[1].chapter.number).toBe(2); // Chapter II
    expect(chapterTriggers[2].chapter.number).toBe(3); // Chapter III  });
  it('adjustCount triggers chapters when incrementing count and crossing thresholds', () => {    const { result } = renderHook(() => useGameState());    act(() =>      result.current.addCard(addInput({        mechanic: 'saga',        startingCount: 1,        direction: 'increment',        targetCount: 3,        chapters: ['Chapter I', 'Chapter II', 'Chapter III'],      }));    const cardId = result.current.state.cards[0]!.getInstanceId();    // Increment count by 1: should not trigger
    act(() => result.current.adjustCount(cardId, 1));    expect(result.current.state.cards[0]!.count).toBe(2);    // Increment to 3: should trigger Chapter III
    act(() => result.current.adjustCount(cardId, 1));    const chapterTriggerLog = result.current.state.log.filter(entry => entry?.chapter);    const chapterTriggers = chapterTriggerLog.filter(      entry => entry.step === 'precombatMain' && entry.to === 3    );    expect(chapterTriggers.length).toBe(1);  });
  it('does not trigger chapter un-crossings on decrement count', () => {    const { result } = renderHook(() => useGameState());    act(() =>      result.current.addCard(addInput({        mechanic: 'saga',        startingCount: 3,        direction: 'increment',        targetCount: 3,        chapters: ['Chapter I', 'Chapter II', 'Chapter III'],      }));    const cardId = result.current.state.cards[0]!.getInstanceId();    act(() => result.current.setCount(cardId, 3));    // Trigger all chapters upfront
    const initialTriggers = result.current.state.log.filter(entry => entry?.chapter);    expect(initialTriggers.length).toBe(3);    // Lower count back past 1: should not trigger any chapter *un-crossings*    act(() => result.current.setCount(cardId, 1));    const chapterTriggersAfterDrop = result.current.state.log.filter(entry => entry?.chapter) as Array<{      chapter: { number: number; text: string };    }>;    expect(chapterTriggersAfterDrop.length).toBe(0);  });});

